const webhookData = $('Webhook').first().json;
const llmResponse = $input.first().json;

try {
  // Extract content from Claude response
  const content = llmResponse.content?.[0]?.text || '';

  // Find JSON in the response (might be wrapped in markdown code blocks)
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const courseData = JSON.parse(jsonStr);

  // Add metadata from webhook
  const enrichedCourse = {
    ...courseData,
    instructor_id: webhookData.body.instructor_id,
    price_credits: webhookData.body.price_credits || 0,
    is_free: webhookData.body.is_free !== false,
    language: webhookData.body.language || 'fr',
    thumbnail_url: webhookData.body.thumbnail_url || null
  };

  return {
    json: {
      success: true,
      course: enrichedCourse,
      guild_id: webhookData.body.guild_id
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse course structure: ' + e.message,
        raw_response: llmResponse.content?.[0]?.text?.substring(0, 500)
      }
    }
  };
}

const apiResponse = $input.first().json;
const parseData = $('Parse LLM Response').first().json;

return {
  json: {
    success: true,
    data: {
      course_id: apiResponse.id,
      title: apiResponse.title,
      status: apiResponse.status,
      modules_count: apiResponse.modules_count || parseData.course.modules?.length || 0,
      total_duration_minutes: apiResponse.total_duration_minutes
    },
    meta: {
      workflow: 'learning-generate-course',
      provider: 'anthropic',
      model: 'claude-3-haiku-20240307',
      timestamp: new Date().toISOString()
    }
  }
};
